declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function box<T>(value: T): { value: T } { return { value }; }
import { list } from "./first";
export const result = compose(list, box);
export const demanded: { value: string[] } = result("text");

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function list<T>(value: T): T[] { return [value]; }
import { box } from "./second";
export const result = compose(list, box);
export const demanded: { value: string[] } = result("text");

import { compose } from "./higher";
import { list, box } from "./factories";
export const result = compose(list, box);
export const demanded: { value: string[] } = result("text");

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
import { list, box } from "./bridge";
export const result = compose(list, box);
export const demanded: { value: string[] } = result("text");

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function box<T>(value: T): { value: T } { return { value }; }
const list: <Element>(value: Element) => Element[] = value => [value];
export const result = compose(list, box);
export const demanded: { value: string[] } = result("text");

declare function container<A, B>(fn: (value: A) => B): { run: (value: A) => B };
function identity<T>(value: T): T { return value; }
export const result = container(identity);

declare function container<A, B>(fn: (value: A) => B): { run: (value: A) => B };
function identity<T>(value: T): T { return value; }
export const result = container(identity);
export const demanded: string = result.run("text");

declare function overloaded<A, B>(fn: (value: A) => B): { (value: A): B; (): B | undefined };
function identity<T>(value: T): T { return value; }
export const result = overloaded(identity);

declare function factory<A, R>(ctor: new (value: A) => R): (value: A) => R;
class Box<T> { value: T; constructor(value: T) { this.value = value; } }
export const result = factory(Box);
export const demanded: Box<string> = result("text");

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function identity<T = string>(value: T): T { return value; }
function list<T>(value: T): T[] { return [value]; }
export const result = compose(identity, list);
export const demanded: number[] = result(1);

declare function restLift<A, B>(fn: (...values: A[]) => B): (...values: A[]) => B[];
function first<T>(...values: T[]): T { return values[0]; }
export const result = restLift(first);

declare function optionalLift<A, B>(fn: (value?: A) => B): (value?: A) => B[];
function optional<T>(value?: T): T | undefined { return value; }
export const result = optionalLift(optional);

declare function lift2<A, B, R>(fn: (left: A, right: B) => R): (left: A, right: B) => R[];
function pair<T, U>(left: T, right: U): [T, U] { return [left, right]; }
export const result = lift2(pair);

declare function lift2<A, B, R>(fn: (left: A, right: B) => R): (left: A, right: B) => R[];
function pair<T, U extends T>(left: T, right: U): [T, U] { return [left, right]; }
export const result = lift2(pair);

declare function lift2<A, B, R>(fn: (left: A, right: B) => R): (left: A, right: B) => R[];
function pair<T = string, U = T[]>(left: T, right: U): [T, U] { return [left, right]; }
export const result = lift2(pair);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
function nested<T>(value: T): <U>(other: U) => [T, U] { return other => [value, other]; }
export const result = lift(nested);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
const provider: { map: <T>(value: T) => T[] } = { map: <T>(value: T): T[] => [value] };
export const result = lift(provider.map);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
const provider = { map<T>(value: T): T[] { return [value]; } };
export const result = lift(provider.map);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
interface Mapper { <T>(value: T): T; }
declare const mapper: Mapper;
export const result = lift(mapper);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
import { mapper } from "./shapes";
export const result = lift(mapper);

function apply<A, B>(value: A, fn: (value: A) => B): B { return fn(value); }
function list<T>(value: T): T[] { return [value]; }
export const result = apply("text", list);

function apply<A, B>(fn: (value: A) => B, value: A): B { return fn(value); }
function list<T>(value: T): T[] { return [value]; }
export const result = apply(list, "text");

declare function guarded<A, B>(fn: (value: A) => B): (value: NoInfer<A>) => B;
function identity<T>(value: T): T { return value; }
export const result = guarded(identity);

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function list<T>(value: T): T[] { return [value]; }
function box<T>(value: T): { value: T } { return { value }; }
export const result = compose<string, string[], { value: string[] }>(list, box);

declare function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C;
function list<T>(value: T): T[] { return [value]; }
function box<T>(value: T): { value: T } { return { value }; }
export const result: (value: boolean) => { value: boolean[] } = compose(list, box);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
declare function convert<T>(value: T): T[];
declare function convert(value: number): number[];
export const result = lift(convert);

declare function lift<A, B>(fn: (value: A) => B): (value: A) => B[];
declare function convert(value: number): number[];
declare function convert<T>(value: T): T[];
export const result = lift(convert);

declare function choose<A, B>(fn: (value: A) => B, mode: "wrap"): (value: A) => B[];
declare function choose<A, B>(fn: (value: A) => B, mode: "keep"): (value: A) => B;
function identity<T>(value: T): T { return value; }
export const result = choose(identity, "wrap");

declare function choose<A, B>(fn: (value: A) => B, mode: "wrap"): (value: A) => B[];
declare function choose<A, B>(fn: (value: A) => B, mode: "keep"): (value: A) => B;
function identity<T>(value: T): T { return value; }
export const result = choose(identity, "invalid");

declare function adapt<A, R>(ctor: new (value: A) => R): new (value: A) => R;
class Box<T> { value: T; constructor(value: T) { this.value = value; } }
export const result = adapt(Box);

function compose<A, B, C>(first: (value: A) => B, second: (value: B) => C): (value: A) => C { return value => second(first(value)); }
function list<T>(value: T): T[] { return [value]; }
function box<T>(value: T): { value: T } { return { value }; }
export const result = compose(list, box);

function lift<A, B>(fn: (value: A) => B): (value: A) => B[] { return value => [fn(value)]; }
function identity<T>(value: T): T { return value; }
export const result = lift(identity);

import { compose } from "./higher.js";
import { list, box } from "./factories.js";
export const result = compose(list, box);

function compose3<A, B, C, D>(one: (value: A) => B, two: (value: B) => C, three: (value: C) => D): (value: A) => D { return value => three(two(one(value))); }
function list<T>(value: T): T[] { return [value]; }
function box<T>(value: T): { value: T } { return { value }; }
export const result = compose3(list, box, list);
